using OpenPlexus.Worlds;
using Xunit.Abstractions;

namespace OpenPlexus.Tests;

/// <summary>
/// The binding world's experiment, on scenes generated in 2017 by people who had
/// never heard of this project.
/// </summary>
/// <remarks>
/// <b>Fork 25 built a world specifically to fail and then lifted it.</b> Every
/// one of those numbers was taken on scenes generated by the same hands that
/// built the mechanism. CLEVR is fifteen thousand scenes of exactly that
/// confusion — two objects whose attributes can be swapped without changing the
/// code set — and it ships the scene graph as JSON, so no vision is needed and
/// none is claimed.
/// </remarks>
public sealed class ClevrTests(ITestOutputHelper output)
{
    /// <summary>
    /// Where the corpus is, or a failure that says how to get it.
    /// </summary>
    /// <remarks>
    /// <b>Fails rather than skipping</b>, which is this suite's standing rule —
    /// see <see cref="Tree"/>.
    /// </remarks>
    private static string Corpus
    {
        get
        {
            var corpus = Path.Combine(Tree.Repo(), "corpora", "CLEVR_v1.0");

            Assert.True(File.Exists(Path.Combine(corpus, "scenes", "CLEVR_val_scenes.json")),
                $"the CLEVR corpus is not at {corpus}. Fetch it with:\n"
                + "    bash corpora/fetch.sh");

            return corpus;
        }
    }

    private static ClevrSettings World(
        int scenes = 120, bool segmented = true, bool tagged = true, bool fleeting = false) => new()
    {
        Corpus = Corpus, Scenes = scenes, Segmented = segmented, Tagged = tagged, Fleeting = fleeting,
    };

    // ---- what the corpus is, asserted rather than described -----------------

    [Fact]
    public void A_scene_is_its_objects_and_every_object_has_four_attributes()
    {
        var world = new Clevr(World(scenes: 20));

        Assert.Equal(20, world.Scenes.Count);

        foreach (var scene in world.Scenes)
        {
            // Four attributes and an index per object, plus one for the scene, so
            // the code count is one more than a multiple of five.
            Assert.Equal(1, scene.Codes.Length % 5);

            Assert.NotNull(scene.Groups);
            Assert.Single(scene.Codes.Where(code => code.Modality == Clevr.Where));

            // And the scene index is always fleeting, whatever the object arm
            // says, or every attribute grows a row entry per scene forever.
            Assert.Contains(Clevr.Seen(scene.Scene), scene.Fleeting!);
        }

        output.WriteLine(
            $"scenes={world.Scenes.Count} asked={world.Asked} chance={world.Chance:F4} " +
            $"codes={world.Scenes.Sum(scene => scene.Codes.Length)}");
    }

    [Fact]
    public void An_index_is_fresh_for_every_object_of_every_scene()
    {
        // An index that came back in a later scene would name a KIND of object,
        // which is the one thing it must not do -- and object 0 of every scene
        // sharing a code would be a hub joining every scene to every other.
        var world = new Clevr(World(scenes: 30));
        var seen = new HashSet<OpenPlexus.Codes.Code>();

        foreach (var code in world.Scenes
                     .SelectMany(scene => scene.Codes)
                     .Where(code => code.Modality == Clevr.Object))
            Assert.True(seen.Add(code), "an object index came back in another scene");
    }

    [Fact]
    public void Only_the_questions_this_architecture_can_answer_are_kept()
    {
        var world = new Clevr(World(scenes: 60));

        Assert.True(world.Asked > 0, "no answerable question was found at all");

        foreach (var scene in world.Scenes)
            foreach (var question in world.About(scene.Scene))
            {
                // A CONJUNCTION, not a single filter -- one filter names a class
                // and the answer is then whatever is commonest, which measures the
                // corpus rather than the binding.
                Assert.True(question.Origins.Length >= 2);

                // And the filters name a different attribute from the answer, or
                // the question would contain its own answer.
                Assert.DoesNotContain(question.Origins, code => code.Modality == question.Asking);
            }
    }

    // ---- what the graph does with it ---------------------------------------

    /// <summary>Enough scenes to put a few hundred questions behind an arm.</summary>
    /// <remarks>
    /// <b>Most of CLEVR is thrown away</b> — see <see cref="Clevr"/> — so a scene
    /// yields well under one answerable question on average.
    /// </remarks>
    private const int Scenes = 700;

}
